INSERT INTO `products` (`id`, `external_id`, `name`, `name_en`, `slug`, `brand`, `category_id`, `category_path`, `price`, `sale_price`, `discount_percent`, `stock`, `stock_status`, `main_image`, `all_images`, `description`, `short_desc`, `warranty`, `seller`, `source_url`, `rating`, `review_count`, `sold`, `views`, `status`, `created_at`, `updated_at`) VALUES
(1, 'dkp-4019035', 'مولتی متر دیجیتال یونی-تی مدل UT33D plus', '', 'مولتی-متر-دیجیتال-یونی-تی-مدل-UT33D-plus-dkp4019035', 'یونی-تی', NULL, 'مولتی متر و ال سی آر متر < مولتی متر', 4900000, 4300000, 12, 10, 'in_stock', 'uploads/pictuer/dkp-4019035.jpg', 'uploads/pictuer/dkp-4019035.jpg', 'مولتی متر دیجیتال مدل UNI-T UT33D Plus از جمله مولتی متر های کوچک و سبک اما با کارایی نسبتا خوب است که با توجه به قیمت ارزان و همچنین استحکام بالا، ارزش خرید بالایی نسبت به قیمت دستگاه دارد. اندازه گیری ولتاژ AC/DC، اندازه گیری جریان AC در حد میکرو آمپر، مقاومت، تست دیود و پیوستگی مدار و ردیابی برق غیر تماسی از جمله امکانات این مولتی متر کوچک است. این مولتی متر به منظور استفاده جهت امور آموزشی و آزمایشگاهی می تواند مورد استفاده قرار بگیرد', 'مولتی متر دیجیتال مدل UNI-T UT33D Plus از جمله مولتی متر های کوچک و سبک اما با کارایی نسبتا خوب است که با توجه به قیمت ارزان و همچنین استحکام بالا، ارزش خرید بالایی نسبت به قیمت دستگاه دارد. اندازه گیری ولتاژ AC/DC، اندازه گیری جریان AC در حد میکرو آمپر، مقاومت، تست دیود و پیوستگی مدار و ردیابی برق غیر تماسی از جمله امکانات این مولتی متر کوچک است. این مولتی متر به منظور استفاده جهت امور آموزشی و آزمایشگاهی می تواند مورد استفاده قرار بگیرد', 'گارانتی اصالت و سلامت فیزیکی کالا', 'کالا پترو پژوهش', 'https://www.digikala.com/product/dkp-4019035/', 85.85, 41, 0, 0, 1, '2026-10-08 22:01:12', '2026-10-11 10:30:08'),
(2, 'dkp-14269399', 'ترکیب گیاهی پروتئینی فدک - 1000 گرم', '', 'ترکیب-گیاهی-پروتئینی-فدک---1000-گرم-dkp14269399', 'متفرقه', NULL, 'غلات ارگانیک < Organic Cereals', 650000, NULL, 0, 10, 'in_stock', 'uploads/pictuer/dkp-14269399.jpg', 'uploads/pictuer/dkp-14269399.jpg', '', '', 'گارانتی اصالت و سلامت فیزیکی کالا', 'فروشگاه بزرگ فدک', 'https://www.digikala.com/product/dkp-14269399/', 84.00, 5, 0, 0, 1, '2026-10-08 22:01:12', '2026-10-11 10:30:08'),
(3, 'dkp-18991772', 'لپ‌تاپ لنوو مدل IdeaPad 1 15IJL7 با پردازنده Celeron N4500، رم DDR4 8GB با فرکانس 2933MHz، حافظه SSD با ظرفیت 256GB، نمایشگر 15.6 اینچ TN با وضوح Full HD', 'Lenovo IdeaPad 1 15IJL7-Celeron N4500-8GB DDR4 2933MHz-256GB SSD-TN FHD 15.6 inch Laptop', 'لپتاپ-لنوو-مدل-IdeaPad-1-15IJL7-با-پردازنده-Celeron-N4500-رم-DDR4-8GB-با-فرکانس--dkp18991772', 'لنوو', NULL, 'لپ تاپ و الترابوک < لپ تاپ و الترابوک', 93000000, NULL, 0, 9, 'in_stock', 'uploads/pictuer/dkp-18991772.jpg', 'uploads/pictuer/dkp-18991772.jpg', 'لپ‌تاپ لنوو IdeaPad 1 15IJL7 با طراحی جمع‌وجور و وزن سبک ۱.۵۵ کیلوگرم برای کاربران عمومی و استفاده روزمره مناسب است. بدنه پلاستیکی با ضخامت ۱۷.۹ میلی‌متر، حمل آسان و دوام کافی را ارائه می‌دهد و ظاهر مینیمال آن برای محیط‌های کاری و خانگی جذابیت دارد. صفحه‌نمایش ۱۵.۶ اینچی TN با وضوح Full HD و روکش مات، تصاویر واضح با رنگ‌های قابل قبول برای وب‌گردی، تماشای فیلم و کارهای سبک فراهم می‌کند و نرخ تازه‌سازی ۶۰ هرتز تجربه‌ای روان برای استفاده روزمره ایجاد می‌کند.\n\nپردازنده Intel Celeron N4500 با دو هسته و دو رشته پردازشی و فرکانس ۱.۱ تا ۲.۸ گیگاهرتز، همراه با گرافیک مجتمع UHD Graphics، عملکرد مناسبی برای مرور وب، کار با اسناد و برنامه‌های سبک دارد. حافظه رم ۸ گیگابایتی DDR4 با فرکانس ۲۹۳۳ مگاهرتز و ترکیب یک اسلات آنبرد و یک اسلات SO-DIMM، امکان اجرای چند برنامه سبک به صورت همزمان و ارتقای حافظه در آینده را فراهم می‌کند. حافظه داخلی ۲۵۶ گیگابایتی SSD با رابط PCIe NVMe سرعت بالای بارگذاری برنامه‌ها و انتقال فایل‌ها را تضمین می‌کند.\n\nباتری سه سلولی ۴۲ وات‌ساعتی با پشتیبانی از شارژ سریع، شارژدهی تا ۱۱ ساعت در حالت استفاده سبک ارائه می‌دهد و مناسب همراهی با کاربر در طول روز است. کیبورد با صفحه کلید اعداد و تاچ‌پد بدون دکمه با پشتیبانی از چند لمس، تجربه تایپ و حرکت روان دست را فراهم می‌کند. دو اسپیکر استریو با فناوری دالبی و وبکم HD با شاتر حریم خصوصی، امکانات چندرسانه‌ای و امنیتی کافی ارائه می‌دهند.\n\nدرگاه‌های ارتباطی متنوع شامل USB 2.0 / USB 3.2 Type-A / USB 3.2 Type-C / HDMI 1.۴ / جک صدا و شبکه Wi-Fi ۶ و بلوتوث ۵.۲، اتصال آسان به دستگاه‌های جانبی و اینترنت را تضمین می‌کنند. این لپ‌تاپ بدون سیستم عامل عرضه شده و گزینه‌ای اقتصادی و کاربردی برای دانش‌آموزان و دانشجویان محسوب می‌شود.', 'لپ‌تاپ لنوو IdeaPad 1 15IJL7 با طراحی جمع‌وجور و وزن سبک ۱.۵۵ کیلوگرم برای کاربران عمومی و استفاده روزمره مناسب است. بدنه پلاستیکی با ضخامت ۱۷.۹ میلی‌متر، حمل آسان و دوام کافی را ارائه می‌دهد و ظاهر مینیمال آن برای محیط‌های کاری و خانگی جذابیت دارد. صفحه‌نمایش ۱۵.۶ اینچی TN با وضوح Full HD و روکش مات، تصاویر واضح با رنگ‌های قابل قبول برای وب‌گردی، تماشای فیلم و کارهای سبک فراهم می‌کند و نرخ تازه‌سازی ۶۰ هرتز تجربه‌ای روان برای استفاده روزمره ایجاد می‌کند.\n\nپردازنده Intel Celeron N4500 ', 'گارانتی 18 ماهه دیجی کالا سرویس', 'دیجی‌کالا', 'https://www.digikala.com/product/dkp-18991772/', 84.34, 212, 0, 0, 1, '2026-10-08 22:01:12', '2026-10-11 13:01:27'),
(4, 'dkp-21190850', 'گوشی موبایل شیائومی مدل Redmi Note 15 4G دو سیم کارت ظرفیت 256 گیگابایت و رم 8 گیگابایت', 'Xiaomi Redmi Note 15 4G Dual SIM Storage 256GB and RAM 8GB Mobile Phone', 'گوشی-موبایل-شیائومی-مدل-Redmi-Note-15-4G-دو-سیم-کارت-ظرفیت-256-گیگابایت-و-رم-8-گ-dkp21190850', 'شیائومی', 4, 'گوشی موبایل < گوشی موبایل', 89999000, NULL, 0, 10, 'in_stock', 'uploads/pictuer/dkp-21190850.jpg', 'uploads/pictuer/dkp-21190850.jpg', 'گوشی  Redmi Note 15 4G ادامه سری پرطرفدار نوت شیائومی است و پیش‌بینی می‌شود به یکی از پرفروش‌ترین‌ میان‌رده‌های سال 2026 تبدیل شود. این گوشی با تمرکز بر نمایشگر باکیفیت، باتری بسیار پرظرفیت و طراحی باریک وارد بازار شده است. با بدنه‌ای به ضخامت ۷.۹ میلی‌متر و وزن حدود ۱۸۴ گرم یک گوشی خوش‌دست است و در کنار گواهی IP64 در برابر گردوغبار و پاشش آب مقاوم است و ترکیبی از ظرافت و دوام را ارائه می‌دهد. نمایشگر ۶.۷۷ اینچی AMOLED با نرخ نوسازی ۱۲۰ هرتز، روشنایی فوق‌العاده ۳۲۰۰ نیت و فناوری PWM با فرکانس بالا، یک تجربه لذت بخش در هنگام تماشای تصاویر هدیه می‌دهد. در بخش سخت‌افزار، تراشه جدید Helio G100 Ultra عملکردی مناسب برای استفاده روزمره و مالتی تسکینگ ارائه می‌دهد و امکان افزایش حافظه از طریق کارت microSD هم فراهم است. دوربین اصلی ۱۰۸ مگاپیکسلی با دیافراگم باز f/1.7 برای ثبت تصاویر پرجزئیات طراحی شده و در کنار آن یک لنز کمکی قرار دارد که امکان عکاسی ندارد. دوربین سلفی ۲۰ مگاپیکسلی هم کیفیت خوبی دارد و نیاز کاربران شبکه‌های اجتماعی را برآورده می‌کند. بلندگوهای استریو با پشتیبانی از Dolby Atmos، حسگر اثرانگشت زیر نمایشگر، باتری حجیم ۶۰۰۰ میلی‌آمپرساعتی با شارژ ۳۳ واتی و قابلیت شارژ معکوس از دیگر ویژگی‌های مهم این مدل محسوب می‌شوند که آن را به گزینه‌ای جذاب در میان گوشی‌های میان‌رده تبدیل می‌کند.', 'گوشی  Redmi Note 15 4G ادامه سری پرطرفدار نوت شیائومی است و پیش‌بینی می‌شود به یکی از پرفروش‌ترین‌ میان‌رده‌های سال 2026 تبدیل شود. این گوشی با تمرکز بر نمایشگر باکیفیت، باتری بسیار پرظرفیت و طراحی باریک وارد بازار شده است. با بدنه‌ای به ضخامت ۷.۹ میلی‌متر و وزن حدود ۱۸۴ گرم یک گوشی خوش‌دست است و در کنار گواهی IP64 در برابر گردوغبار و پاشش آب مقاوم است و تر