(415, 'dkp-20001266', 'گوشی موبایل هانوفر مدل 5720 ظرفیت 128 مگابایت', '', 'گوشی-موبایل-هانوفر-مدل-5720-ظرفیت-128-مگابایت-dkp20001266', 'هانوفر', 4, 'گوشی موبایل < گوشی موبایل', 0, NULL, 0, 1, 'in_stock', 'uploads/pictuer/dkp-20001266.jpg', 'uploads/pictuer/dkp-20001266.jpg', '', '', '', '', 'https://www.digikala.com/product/dkp-20001266/', 56.33, 49, 0, 0, 1, '2026-10-08 22:01:14', '2026-10-11 10:30:08');
