INSERT INTO `product_specs` (`id`, `product_id`, `group_name`, `spec_key`, `spec_value`, `sort_order`, `created_at`) VALUES
(29669, 818, 'مشخصات فنی', 'مشخصات دوربین اصلی', 'دارای 4 حسگر دوربین | دوربین‌هایی با رزولوشن 200+10+10+12 مگاپیکسل - حسگر اول از نوع عریض (Wide)، با رزولوشن 200 مگاپیکسل، دریچه‌ی دیافراگم f/1.7، فاصله کانونی لنز 24 میلی‌متر (Focal Length 24 mm)، ثبت تصاویر با پیکسل‎هایی به سایز 0.6 میکرومتر (0.6µm Pixel Size)، سایز سنسور 1/1.3 اینچ (Sensor Size 1/1.3 Inch)، مجهز به فناوری فوکوس اتوماتیک از نوع PDAF و مجهز به لرزشگیر اپتیکال تصویر (Optical Image Stabilization) و Laser AF / - حسگر دوم از نوع تله‌فوتو پریسکوپ (Periscope Telephoto) با رزولوشن 10 مگاپیکسل، دریچه‌ی دیافراگم f/4.9، فاصله کانونی لنز 230 میلی‌متر (Focal Length 230mm)، ثبت تصاویر با پیکسل‎هایی به سایز 1.12 میکرومتر (1.12µm Pixel Size)، سایز سنسور 1/3.52 اینچ (Sensor Size 1/3.52 Inch)، مجهز به فناوری فوکوس اتوماتیک از نوع PDAF و مجهز به لرزشگیر اپتیکال تصویر (Optical Image Stabilization) و همراه با زوم اپتیکال 10 برابر (10x optical zoom) / - حسگر سوم از نوع تله‌فوتو (Telephoto) با رزولوشن 10 مگاپیکسل، دریچه‌ی دیافراگم f/2.4، فاصله کانونی لنز 70 میلی‌متر (Focal Length 70mm)، ثبت تصاویر با پیکسل‎هایی به سایز 1.12 میکرومتر (1.12µm Pixel Size)، سایز سنسور 1/3.52 اینچ (Sensor Size 1/3.52 Inch)، مجهز به فناوری فوکوس اتوماتیک از نوع PDAF و مجهز به لرزشگیر اپتیکال تصویر (Optical Image Stabilization) و همراه با زوم اپتیکال 3 برابر (3x Optical Zoom) / - حسگر چهارم از نوع فوق‌عریض (ultrawide) با رزولوشن 12 مگاپیکسل، دریچه‌ی دیافراگم f/2.2، فاصله کانونی لنز 13 میلی‌متر (Focal Length 13mm)، ثبت تصاویر با پیکسل‎هایی به سایز 1.4 میکرومتر (1.4µm Pixel Size)، سایز سنسور 1/2.55 اینچ (Sensor Size 1/2.55 Inch)، مجهز به فناوری فوکوس اتوماتیک دوگانه از نوع PDAF و مجهز به فوق لرزشگیر ویدئو (Super Steady video) و زاویه دید 120 درجه / قابلیت عکاسی پانوراما (Panorama) قابلیت عکاسی HDR به‌صورت خودکار', 34, '2026-10-08 22:01:17'),
(29670, 818, 'مشخصات فنی', 'فناوری فوکوس', 'PDAF', 35, '2026-10-08 22:01:17'),
(29671, 818, 'مشخصات فنی', 'سایر مشخصات فیلمبرداری', 'رزولوشن 3240 × 7680 و سرعت 24/30 فریم بر ثانیه (8k@24/30FPS) / رزولوشن 2160 × 3840 و سرعت 30/60 فریم بر ثانیه (4K@30/60FPS) / رزولوشن 1080 × 1920 و سرعت 30/60/240/960 فریم بر ثانیه (1080p@30/60/240/960FPS) / stereo sound rec / HDR10+', 36, '2026-10-08 22:01:17'),
