INSERT INTO `product_specs` (`id`, `product_id`, `group_name`, `spec_key`, `spec_value`, `sort_order`, `created_at`) VALUES
(56699, 1519, 'مشخصات فنی', 'مشخصات دوربین اصلی', 'دارای چهار حسگر دوربین - حسگر اول از نوع عریض (Wide) با رزولوشن 48 مگاپیکسل، دریچه‌ی دیافراگم f/2.0، فاصله کانونی لنز 26 میلی‌متر (Focal Length 26 mm)، سایز سنسور 1/2.0 اینچ (&amp;#39;&amp;#39;Sensor Size 1/2.0)، ثبت تصاویر با پیکسل‎هایی به سایز 0.8 میکرومتر (0.8µm Pixel Size) همراه با فناوری فوکوس اتوماتیک Phase Detection - حسگر دوم از نوع فوق عریض (Ultrawide) با رزولوشن 12 مگاپیکسل، دریچه‌ی دیافراگم f/2.2، فاصله کانونی لنز 13 میلی‌متر (Focal Length 13 mm) و ثبت تصاویر با پیکسل‎هایی به سایز 1.12 میکرومتر (1.12µm Pixel Size) - حسگر سوم از نوع تله‌فوتو (Telephoto) با رزولوشن 5 مگاپیکسل، دریچه‌ی دیافراگم f/2.4، فاصله کانونی لنز 40 میلی‌متر (Focal Length 40 mm) - لنز ماکرو - حسگر چهارم از نوع عریض (Wide) با رزولوشن 5 مگاپیکسل، دریچه‌ی دیافراگم f/2.2، سایز سنسور 1/5.0 اینچ (&amp;#39;&amp;#39;Sensor Size 1/5.0)، ثبت تصاویر با پیکسل‎هایی به سایز 1.12 میکرومتر (1.12µm Pixel Size) - لنز عمق قابلیت ثبت موقعیت جغرافیایی عکس‌ها و فیلم‌ها (Geo-Tagging) قابلیت فوکوس با اشاره روی سوژه (Touch Focus) قابلیت تشخیص چهره (Face Detection) قابلیت عکاسی پانوراما (Panorama) قابلیت عکاسی HDR', 33, '2026-10-08 22:01:21'),
(56700, 1519, 'مشخصات فنی', 'سایر مشخصات فیلمبرداری', 'رزولوشن 2160 × 3840 و سرعت 30 فریم بر ثانیه (2160p@30FPS) رزولوشن 1080 × 1920 و سرعت 30 فریم بر ثانیه (1080p@30FPS) رزولوشن 1080 × 1920 و سرعت 60 فریم بر ثانیه (1080p@60FPS) رزولوشن 1080 × 1920 و سرعت 120 فریم بر ثانیه (1080p@120FPS) با تثبیت کننده الکترونیکی تصویر مبتنی بر ژیروسکوپ (gyro-EIS)', 34, '2026-10-08 22:01:21'),
(56701, 1519, 'مشخصات فنی', 'فلش', 'LED', 35, '2026-10-08 22:01:21'),
(56702, 1519, 'مشخصات فنی', 'مشخصات دوربین سلفی', 'حسگری از نوع عریض (Wide) با رزولوشن 32 مگاپیکسل، دریچه‌ی دیافراگم f/2.2، فاصله کانونی لنز 26 میلی‌متر (Focal Length 26 mm)، سایز سنسور 1/2.8 اینچ (&amp;#39;&amp;#39;Sensor Size 1/2.8)، ثبت تصاویر با پیکسل‎هایی به سایز 0.8 میکرومتر (0.8µm Pixel Size) قابلیت عکاسی HDR فیلمبرداری: رزولوشن 1080 × 1920 و سرعت 30 فریم بر ثانیه (1080p@30FPS)', 36, '2026-10-08 22:01:21'),
